/* Fictional, local-only design fixtures. No backend or notification sends. */
(() => {
  'use strict';
  const directions = {
    a: ['Overview', 'Refined table · See the breached condition, open any row, or acknowledge directly.'],
    b: ['Evidence', 'Evidence-led · See both breached windows before opening an alert.'],
    c: ['Workspace', 'Investigation-led · Keep the queue beside the evidence as you work.'],
    d: ['Focus', 'One decision at a time · Give the next unacknowledged alert your full attention.'],
    e: ['Timeline', 'Time as the index · Find overlapping alerts without implying a shared cause.'],
  };
  const seed = [
    {id:'checkout',name:'Checkout availability',service:'Checkout',policy:'Checkout fast burn',state:'firing',severity:'High',since:'10:24',age:'18 min',short:22.8,long:18.6,threshold:14.4,sw:5,lw:60,badS:228,totalS:10000,badL:1116,totalL:60000,start:70,end:100},
    {id:'checkout-sustained',name:'Checkout availability',service:'Checkout',policy:'Checkout sustained burn',state:'firing',severity:'Medium',since:'10:32',age:'10 min',short:12.5,long:7.4,threshold:6,sw:30,lw:360,badS:375,totalS:30000,badL:2664,totalL:360000,start:83,end:100},
    {id:'payments',name:'Payment success',service:'Payments',policy:'Payments sustained burn',state:'firing',severity:'High',since:'10:11',age:'31 min',short:8.1,long:6.8,threshold:6,sw:30,lw:360,badS:243,totalS:30000,badL:2448,totalL:360000,start:48,end:100},
    {id:'search',name:'Search response time',service:'Search',policy:'Search fast burn',state:'ack',severity:'High',since:'10:05',age:'37 min',short:19.2,long:16.4,threshold:14.4,sw:5,lw:60,badS:192,totalS:10000,badL:984,totalL:60000,start:38,end:100,actor:'Ari Chen',ackTime:'10:29',stale:true},
    {id:'catalog',name:'Catalog availability',service:'Catalog',policy:'Catalog fast burn',state:'resolved',severity:'High',since:'09:48',resolved:'10:06',age:'18 min',short:0.6,long:12.8,threshold:14.4,sw:5,lw:60,badS:6,totalS:10000,badL:768,totalL:60000,start:10,end:40},
    {id:'export',name:'Export completion',service:'Exports',policy:'Exports fast burn',state:'resolved',severity:'High',since:'09:51',resolved:'10:02',age:'11 min',short:0.8,long:9.6,threshold:14.4,sw:5,lw:60,badS:8,totalS:10000,badL:576,totalL:60000,start:15,end:33,late:true},
  ];
  let alerts = structuredClone(seed), policies = [], filter='open', search='', selected='checkout', draft, success='';
  let groupBy='none';
  const columnFilters={alert:'',slo:'',state:'',evidence:'',age:'',severity:''};
  const clearColumnFilters=()=>Object.keys(columnFilters).forEach(key=>columnFilters[key]='');
  const root = document.getElementById('app');
  const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const duration = m => m < 60 ? `${m} min` : m % 60 ? `${m} min` : `${m/60} h`;
  const count = n => n.toLocaleString('en-US');
  const stateLabel = s => ({firing:'Firing',ack:'Acknowledged',resolved:'Resolved',normal:'Normal'}[s]);
  const badge = s => `<span class="badge ${s}">${stateLabel(s)}</span>`;
  const route = () => {const [variant,view,id] = location.hash.slice(1).split('/');return {variant:directions[variant]?variant:'a',view:view||'list',id};};
  const href = (view='list',id='') => `#${route().variant}/${view}${id?'/'+id:''}`;
  let conditionSequence=0;
  const newCondition=kind=>({id:'condition-'+(++conditionSequence),short:kind==='fast'?'5':kind==='sustained'?'30':'',shortUnit:'min',long:kind==='fast'?'1':kind==='sustained'?'6':'',longUnit:'h',threshold:kind==='fast'?'14.4':kind==='sustained'?'6':''});
  const initialDraft = () => ({conditions:[newCondition('fast'),newCondition('sustained')],name:'',slo:'',preset:'fast',short:'5',long:'60',threshold:'14.4',severity:'High'});
  const say = message => {const el=document.getElementById('announcement');el.textContent=message;clearTimeout(say.timer);say.timer=setTimeout(()=>el.textContent='',3500);};
  function shell() {
    const ops=document.querySelector('.planned');
    ops.outerHTML='<a class="current" href="#a/list"><svg viewBox="0 0 24 24"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg>Alerts</a>';
    document.querySelectorAll('.sidebar a[href="#"]').forEach(a=>{a.removeAttribute('href');a.setAttribute('aria-disabled','true');});
    document.querySelector('.account').innerHTML='<div class="id"><span class="avatar">J</span><span><strong>Jamie Morgan</strong><small>Administrator · mock user</small></span></div>';
  }
  function review() {
    const r=route();
    document.getElementById('review').innerHTML=`<aside class="review" aria-label="Design review controls"><div class="review-top"><small>Design exploration / fictional data / 12 Nov 2026</small><div class="review-tools"><button class="quiet" data-action="theme">${document.documentElement.classList.contains('dark')?'Light':'Dark'} theme</button><button class="quiet" data-action="reset">Reset demo</button></div></div><nav class="options" aria-label="Design directions">${Object.entries(directions).map(([key,[label]])=>`<a href="#${key}/${r.view}${r.id?'/'+r.id:''}" ${r.variant===key?'aria-current="page"':''}>${key.toUpperCase()} <span>· ${label}</span></a>`).join('')}</nav><p class="design-note">${directions[r.variant][1]}</p></aside>`;
    document.getElementById('review').classList.toggle('compact-review',r.variant==='a'||(r.variant==='c'&&r.view==='new'));
    document.querySelector('.sidebar a.current').href=href();
  }
  function header(title,subtitle='',action=true) {
    return `<div class="heading"><div><h1 tabindex="-1">${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${action?`<a class="btn ${['c','d','e'].includes(route().variant)&&route().view==='list'?'':'primary'}" href="${href('new')}">＋ New alert policy</a>`:''}</div>`;
  }
  const tabs = active => `<nav class="tabs" aria-label="Alerts sections"><a href="${href()}" ${active==='list'?'aria-current="page"':''}>Active <span class="count">${alerts.filter(a=>a.state!=='resolved').length}</span></a><a href="${href('history')}" ${active==='history'?'aria-current="page"':''}>History</a><a href="${href('policies')}" ${active==='policies'?'aria-current="page"':''}>Policies <span class="count">${seed.length+policies.length}</span></a></nav>`;
  const funnel='<svg aria-hidden="true" viewBox="0 0 16 16"><path d="M2 3h12L9 8v4l-2 1V8Z"/></svg>';
  const filterLabels={alert:'Alert name',slo:'SLO',state:'State',evidence:'Evidence',age:'Open for',severity:'Severity'};
  const filterOptions=()=>({slo:[['','All SLOs'],...[...new Set(alerts.filter(a=>a.state!=='resolved').map(a=>a.name))].map(name=>[name,name])],state:[['','All open'],['firing','Firing'],['ack','Acknowledged']],evidence:[['','All evidence'],['fast','14.4× threshold'],['sustained','6× threshold'],['fresh','Fresh evidence'],['stale','Stale evidence']],age:[['','Any duration'],['15','15+ minutes'],['30','30+ minutes']],severity:[['','All severities'],['High','High'],['Medium','Medium'],['Low','Low']]});
  function filterField(key){const options=filterOptions()[key];return `<div class="field"><label for="filter-${key}">${filterLabels[key]}</label>${options?`<select id="filter-${key}" name="${key}">${options.map(([value,label])=>`<option value="${esc(value)}" ${columnFilters[key]===value?'selected':''}>${esc(label)}</option>`).join('')}</select>`:`<input id="filter-${key}" name="${key}" placeholder="Contains…" value="${esc(columnFilters[key])}">`}</div>`;}
  function filterHeader(key,label){return `<button class="column-filter ${columnFilters[key]||(key==='alert'&&columnFilters.severity)?'is-filtered':''}" data-filter="${key}" aria-label="Filter ${label}" aria-haspopup="dialog" aria-expanded="false">${label}${funnel}</button>`;}
  function activeFilters(){const entries=Object.entries(columnFilters).filter(([,value])=>value);return entries.length?`<div class="active-filters" aria-label="Applied filters">${entries.map(([key,value])=>`<button data-remove-filter="${key}" aria-label="Remove ${filterLabels[key]} filter">${filterLabels[key]}: ${esc(filterOptions()[key]?.find(([v])=>v===value)?.[1]||value)} <span aria-hidden="true">×</span></button>`).join('')}<button class="quiet" data-action="clear-filters">Clear all</button></div>`:'';}
  function toolbar(history=false) {
    const refined=route().variant==='a'&&!history, n=Object.values(columnFilters).filter(Boolean).length;
    return `<div class="toolbar ${refined?'compact-toolbar':''}"><label class="sr-only" for="search">Search alerts</label><input id="search" placeholder="Search alerts, SLOs or services…" value="${esc(search)}">${refined?`<div class="list-tools"><button class="quiet filter-trigger" data-filter="all" aria-haspopup="dialog" aria-expanded="false">${funnel}Filters${n?` <span class="filter-count">${n}</span>`:''}</button><span class="tool-divider" aria-hidden="true"></span><button class="quiet group-toggle" id="group-by" data-action="group" aria-pressed="${groupBy==='slo'}"><svg aria-hidden="true" viewBox="0 0 16 16"><path d="M2 3h12M5 7h9M5 11h9M2 6v7"/></svg>Group by SLO</button></div>`:`<label class="sr-only" for="state-filter">Alert state</label><select id="state-filter">${(history?[['resolved','Resolved']]:[['open',route().variant==='e'?'Open + recent':'All open'],['firing','Firing'],['ack','Acknowledged']]).map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select><span class="stamp">Snapshot · 10:42 UTC</span>`}</div>${refined?activeFilters():''}`;
  }
  const filterPanel=document.createElement('div');
  filterPanel.id='filter-panel';filterPanel.className='filter-panel';filterPanel.setAttribute('popover','auto');filterPanel.setAttribute('role','dialog');filterPanel.setAttribute('aria-labelledby','filter-panel-title');document.body.append(filterPanel);
  let filterTrigger;
  function openFilter(trigger){
    filterPanel.hidePopover();filterTrigger=trigger;
    const key=trigger.dataset.filter,keys=key==='all'?Object.keys(columnFilters):key==='alert'?['alert','severity']:[key];
    filterPanel.innerHTML=`<form id="filter-form"><div class="filter-panel-head"><strong id="filter-panel-title">${key==='all'?'Filter alerts':key==='alert'?'Filter alert':'Filter '+filterLabels[key].toLowerCase()}</strong><button type="button" class="quiet" data-action="close-filter" aria-label="Close filters">×</button></div><div class="filter-fields">${keys.map(filterField).join('')}</div><div class="filter-panel-actions"><button type="button" class="quiet" data-action="reset-panel">Reset</button><button class="btn primary" type="submit">Apply</button></div></form>`;
    const rect=trigger.getBoundingClientRect();
    filterPanel.style.left=Math.max(12,Math.min(rect.left,innerWidth-332))+'px';
    filterPanel.style.top=Math.max(12,Math.min(rect.bottom+8,innerHeight-(key==='all'?580:260)))+'px';
    filterPanel.showPopover();filterPanel.style.top=Math.max(12,Math.min(rect.bottom+8,innerHeight-filterPanel.getBoundingClientRect().height-12))+'px';trigger.setAttribute('aria-expanded','true');filterPanel.querySelector('input,select')?.focus();
  }
  filterPanel.addEventListener('toggle',e=>{if(e.newState==='closed')filterTrigger?.setAttribute('aria-expanded','false');});
  function closeFilter(){filterPanel.hidePopover();filterTrigger?.setAttribute('aria-expanded','false');}
  function matchesColumns(a){return a.policy.toLowerCase().includes(columnFilters.alert.trim().toLowerCase())&&(!columnFilters.slo||a.name===columnFilters.slo)&&(!columnFilters.state||a.state===columnFilters.state)&&(!columnFilters.severity||a.severity===columnFilters.severity)&&(!columnFilters.evidence||(columnFilters.evidence==='stale'?a.stale:columnFilters.evidence==='fresh'?!a.stale:columnFilters.evidence==='fast'?a.threshold===14.4:a.threshold===6))&&(!columnFilters.age||parseFloat(a.age)>=Number(columnFilters.age));}
  function visible(history=false) {return alerts.filter(a=>(history?a.state==='resolved':route().variant==='e'&&filter==='open'?true:a.state!=='resolved'&&(route().variant==='a'||filter==='open'||a.state===filter))&&`${a.name} ${a.service} ${a.policy}`.toLowerCase().includes(search.toLowerCase())&&(history||route().variant!=='a'||matchesColumns(a)));}
  const stats = () => `<div class="stats"><span class="attention"><strong>${alerts.filter(a=>a.state==='firing').length}</strong>firing</span><span><strong>${alerts.filter(a=>a.state==='ack').length}</strong>being handled</span><span><strong>2</strong>resolved today</span></div>`;
  function table(items) {
    if(route().variant==='a'&&route().view==='list')return refinedTable(items);
    return `<div class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Alert / SLO</th><th>State</th><th>Severity</th><th>Started · UTC</th><th>Duration</th></tr></thead><tbody>${items.map(a=>`<tr><td><a class="alert-title" href="${href('detail',a.id)}">${a.name}</a><span class="subline">${a.service} · ${a.policy}</span>${a.late?'<span class="subline">Detected after recovery · 10:20 UTC</span>':''}</td><td>${badge(a.state)}${a.actor?`<span class="subline">${a.actor}</span>`:''}${a.stale?'<span class="subline">Evidence stale</span>':''}</td><td><span class="severity">${a.severity}</span></td><td class="mono">${a.since}</td><td class="mono">${a.age}</td></tr>`).join('')}</tbody></table></div>${pager(items.length)}</div>`;
  }
  function refinedRow(a){return `<tr data-open="${a.id}"><td class="alert-identity"><a class="alert-title" href="${href('detail',a.id)}">${a.policy}</a><span class="subline severity">${a.severity} severity</span></td><td class="alert-slo"><span>${a.name}</span><span class="subline">${a.service}</span></td><td class="alert-state">${badge(a.state)}${a.actor?`<span class="subline">${a.actor}</span><span class="ack-at">at ${a.ackTime} UTC</span>`:''}</td><td class="alert-condition"><div class="condition-values"><span><small>${duration(a.sw)}</small><strong>${a.short.toFixed(1)}×</strong></span><span><small>${duration(a.lw)}</small><strong>${a.long.toFixed(1)}×</strong></span></div><span class="condition-threshold">Both ≥ ${a.threshold}× burn</span>${a.stale?'<span class="evidence-stale">Evidence stale · last usable 10:36 UTC</span>':''}</td><td class="alert-age"><span class="mono">${a.age}</span><span class="subline">since ${a.since} UTC</span></td><td class="alert-actions">${a.state==='firing'?`<button class="btn row-ack" data-ack="${a.id}" aria-label="Acknowledge ${a.policy}">Acknowledge</button>`:`<a class="row-view" href="${href('detail',a.id)}" aria-label="View ${a.policy}">View alert <span aria-hidden="true">→</span></a>`}</td></tr>`;}
  function refinedTable(items) {
    const groups=new Map();items.forEach(a=>{if(!groups.has(a.name))groups.set(a.name,[]);groups.get(a.name).push(a);});
    const rows=groupBy==='slo'?[...groups].map(([name,group])=>`<tbody class="slo-group"><tr class="slo-group-heading"><th colspan="6" scope="rowgroup"><span>${name}</span><small>${group.length} ${group.length===1?'alert':'alerts'} · ${group.filter(a=>a.state==='firing').length} firing</small></th></tr>${group.map(refinedRow).join('')}</tbody>`).join(''):`<tbody>${items.map(refinedRow).join('')}</tbody>`;
    return `<div class="panel"><div class="table-scroll"><table class="data-table alert-table"><caption class="sr-only">Open alerts, optionally grouped by SLO. Use column headers to filter.</caption><thead><tr><th scope="col">${filterHeader('alert','Alert')}</th><th scope="col">${filterHeader('slo','SLO')}</th><th scope="col">${filterHeader('state','State')}</th><th scope="col">${filterHeader('evidence','Why it’s open')}</th><th scope="col">${filterHeader('age','Open for')}</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead>${items.length?rows:'<tbody><tr><td class="empty" colspan="6"><h2>No matching alerts</h2><p>Change a filter or clear all to see open alerts.</p><button class="btn" data-action="clear-filters">Clear filters</button></td></tr></tbody>'}</table></div>${pager(items.length)}</div>`;
  }
  function pager(n){return `<div class="pager"><span>${n?'1–'+n:'0'} of ${n}</span><span class="flex"><label>Rows <select aria-label="Rows per page"><option>10</option><option>20</option></select></label><button class="quiet" disabled aria-label="Previous page">←</button><button class="quiet" disabled aria-label="Next page">→</button></span></div>`;}
  function meters(a) {return `<div class="meters">${[['Recent',a.sw,a.short],['Sustained',a.lw,a.long]].map(([l,w,v])=>`<div><div class="meter-label"><span>${duration(w)} · ${l}</span><span>${v.toFixed(1)}× <small>/ ${a.threshold}×</small></span></div><div class="burn-track"><i style="width:${Math.min(100,v/(a.threshold*2)*100)}%"></i><b aria-hidden="true"></b></div></div>`).join('')}</div>`;}
  function evidenceList(items){return `<div class="panel">${items.map(a=>`<article class="evidence-row"><div><a class="alert-title" href="${href('detail',a.id)}">${a.name}</a><span class="subline">${a.service} · started ${a.since} UTC</span><div class="row-meta">${badge(a.state)}<span class="severity">${a.severity} severity</span></div></div><div>${meters(a)}${a.stale?'<p class="subline">Last usable evidence · 10:36 UTC</p>':''}</div><div><p class="note">${a.actor?`Handled by ${a.actor}`:'Both windows exceed the threshold'}</p><a class="btn" href="${href('detail',a.id)}">Investigate →</a></div></article>`).join('')}${pager(items.length)}</div>`;}
  function queue(items){return `<nav class="panel queue" aria-label="Alert queue">${items.map(a=>`<button class="queue-item" data-select="${a.id}" ${selected===a.id?'aria-current="true"':''}><span class="alert-title">${a.name}</span><span class="subline">${a.service} · ${a.age}</span>${badge(a.state)}</button>`).join('')}</nav>`;}
  function windowCards(a){return `<div class="paired">${[['Recent window',a.sw,a.short,a.badS,a.totalS],['Sustained window',a.lw,a.long,a.badL,a.totalL]].map(([label,w,value,bad,total])=>`<div class="window-card ${a.state==='resolved'?'resolved':''}"><div class="label">${label} · ${duration(w)}</div><div class="value">${value.toFixed(1)}×</div><small>Threshold ≥ ${a.threshold}×</small><span class="subline">${count(bad)} bad / ${count(total)} events</span></div>`).join('')}</div>`;}
  const minute=t=>{const [h,m]=t.split(':').map(Number);return h*60+m;};
  const clockLabel=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;
  function chartSamples(a){
    const start=582,end=a.stale?636:642,fired=minute(a.since),resolved=a.resolved?minute(a.resolved):null;
    const times=[...new Set([...Array.from({length:13},(_,i)=>start+i*5).filter(t=>t<=end),fired,...(resolved?[resolved]:[]),end])].sort((x,y)=>x-y);
    return times.map(t=>{
      if(t===end)return {t,short:a.short,long:a.long};
      if(t<fired){const f=(t-start)/(fired-start);return {t,short:a.threshold*(.16+.96*f),long:a.threshold*(.12+.78*f)};}
      if(resolved&&t>=resolved){const f=(t-resolved)/(end-resolved);return {t,short:a.threshold*.7*(1-f)+a.short*f,long:a.threshold*1.1*(1-f)+a.long*f};}
      const f=(t-fired)/((resolved||end)-fired);return {t,short:a.threshold*1.05*(1-f)+(resolved?a.threshold*1.6:a.short)*f,long:a.threshold*(1-f)+(resolved?a.threshold*1.2:a.long)*f};
    });
  }
  function chart(a){
    const samples=chartSamples(a),max=Math.ceil(Math.max(...samples.flatMap(p=>[p.short,p.long]),a.threshold)*1.2),x=t=>50+(t-582)/60*820,y=v=>190-v/max*160;
    const path=key=>samples.map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(1)},${y(p[key]).toFixed(1)}`).join(' ');
    return `<div class="burn-chart-heading"><h2>Burn rate</h2><span class="chart-caption">12 Nov · UTC</span></div><div class="burn-inspect" data-chart="${a.id}" tabindex="0" role="slider" aria-label="Inspect burn rate over time" aria-valuemin="0" aria-valuemax="${samples.length-1}" aria-valuenow="${samples.length-1}" aria-valuetext="${clockLabel(samples.at(-1).t)} UTC. ${duration(a.sw)} burn ${a.short.toFixed(1)} times; ${duration(a.lw)} burn ${a.long.toFixed(1)} times." aria-describedby="chart-help-${a.id}"><svg class="chart" viewBox="0 0 900 225" aria-hidden="true">${[0,max/2,max].map(v=>`<line class="grid" x1="50" x2="870" y1="${y(v)}" y2="${y(v)}"/><text x="40" y="${y(v)+4}" text-anchor="end">${v}×</text>`).join('')}${a.stale?`<rect class="stale-zone" x="${x(636)}" y="25" width="${x(642)-x(636)}" height="165"/>`:''}<line class="threshold" x1="50" x2="870" y1="${y(a.threshold)}" y2="${y(a.threshold)}"/><text x="55" y="${y(a.threshold)-8}">${a.threshold}× threshold</text><path class="series" d="${path('short')}"/><path class="series long" d="${path('long')}"/>${samples.map(p=>`<circle class="sample-dot short" cx="${x(p.t)}" cy="${y(p.short)}" r="2.4"/><circle class="sample-dot long" cx="${x(p.t)}" cy="${y(p.long)}" r="2.4"/>`).join('')}<g class="chart-cursor" hidden><line y1="25" y2="190"/><circle class="short" r="4"/><circle class="long" r="4"/></g>${[582,612,642].map(t=>`<text x="${x(t)}" y="216" text-anchor="${t===582?'start':t===642?'end':'middle'}">${clockLabel(t)}</text>`).join('')}</svg><div class="burn-tooltip" hidden></div></div><div class="chart-footer"><div class="legend"><span><i></i>${duration(a.sw)} burn</span><span><i class="long"></i>${duration(a.lw)} burn</span>${a.stale?'<span>Shaded: no fresh evaluation</span>':''}</div><span class="sr-only" id="chart-help-${a.id}">Use left and right arrow keys to inspect chart values.</span></div>`;
  }
  function inspectChart(el,index){
    const a=alerts.find(a=>a.id===el.dataset.chart),samples=chartSamples(a),i=Math.max(0,Math.min(samples.length-1,index)),p=samples[i];
    const max=Math.ceil(Math.max(...samples.flatMap(p=>[p.short,p.long]),a.threshold)*1.2),x=50+(p.t-582)/60*820,y=v=>190-v/max*160;
    el.dataset.index=i;el.setAttribute('aria-valuenow',i);el.setAttribute('aria-valuetext',`${clockLabel(p.t)} UTC. ${duration(a.sw)} burn ${p.short.toFixed(1)} times; ${duration(a.lw)} burn ${p.long.toFixed(1)} times. Threshold ${a.threshold} times.`);
    const cursor=el.querySelector('.chart-cursor');cursor.removeAttribute('hidden');cursor.querySelector('line').setAttribute('x1',x);cursor.querySelector('line').setAttribute('x2',x);cursor.querySelectorAll('circle').forEach((dot,j)=>{dot.setAttribute('cx',x);dot.setAttribute('cy',y(j?p.long:p.short));});
    const tip=el.querySelector('.burn-tooltip');tip.hidden=false;tip.innerHTML=`<strong>${clockLabel(p.t)} UTC</strong><div><span>${duration(a.sw)} window</span><b>${p.short.toFixed(1)}×</b></div><div><span>${duration(a.lw)} window</span><b>${p.long.toFixed(1)}×</b></div><small>Threshold ${a.threshold}× · ${p.short>=a.threshold&&p.long>=a.threshold?'both meet threshold':'condition not met'}</small>`;
    tip.style.left=Math.max(0,Math.min(el.clientWidth-tip.offsetWidth,x/900*el.clientWidth+12))+'px';
  }
  function hideChart(el){el.querySelector('.chart-cursor').setAttribute('hidden','');el.querySelector('.burn-tooltip').hidden=true;}
  function chartPointer(e){const el=e.target.closest('[data-chart]');if(!el)return;const rect=el.querySelector('svg').getBoundingClientRect(),t=582+((e.clientX-rect.left)/rect.width*900-50)/820*60,samples=chartSamples(alerts.find(a=>a.id===el.dataset.chart));inspectChart(el,samples.reduce((best,p,i)=>Math.abs(p.t-t)<Math.abs(samples[best].t-t)?i:best,0));}
  document.addEventListener('pointermove',chartPointer);
  document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-chart]')){e.target.closest('[data-chart]').focus({preventScroll:true});chartPointer(e);}});
  document.addEventListener('pointerout',e=>{const el=e.target.closest('[data-chart]');if(el&&!el.contains(e.relatedTarget)&&document.activeElement!==el)hideChart(el);});
  document.addEventListener('focusin',e=>{if(e.target.matches('[data-chart]'))inspectChart(e.target,chartSamples(alerts.find(a=>a.id===e.target.dataset.chart)).length-1);});
  document.addEventListener('focusout',e=>{if(e.target.matches('[data-chart]'))hideChart(e.target);});
  document.addEventListener('keydown',e=>{const el=e.target.closest('[data-chart]');if(!el)return;const last=chartSamples(alerts.find(a=>a.id===el.dataset.chart)).length-1,i=Number(el.dataset.index??last);if(['ArrowLeft','ArrowRight','Home','End','Escape'].includes(e.key)){e.preventDefault();if(e.key==='Escape')hideChart(el);else inspectChart(el,e.key==='Home'?0:e.key==='End'?last:i+(e.key==='ArrowRight'?1:-1));}});
  const sloLink=a=>`../slo-detail-options/index.html?slo=${encodeURIComponent(a.name)}&theme=${document.documentElement.classList.contains('dark')?'dark':'light'}#b`;
  function evidence(a){return `<details class="panel calculation"><summary>How this is calculated</summary><div class="inset"><div class="allowance-explainer"><h3>A 99.9% target allows 0.1% unsuccessful events.</h3><p>Burn rate compares the observed error rate with that allowance. A burn rate of <strong>1×</strong> uses the allowance at its intended rate; <strong>${a.threshold}×</strong> is this policy’s alert threshold.</p></div><div class="calculation-windows">${[['Recent window',a.sw,a.short,a.badS,a.totalS],['Sustained window',a.lw,a.long,a.badL,a.totalL]].map(([label,w,burn,bad,total])=>`<section class="calculation-window"><h3>${label} <span>${duration(w)}</span></h3><dl><div><dt>Unsuccessful events</dt><dd>${count(bad)} <small>of ${count(total)}</small></dd></div><div><dt>Observed error rate</dt><dd>${(bad/total*100).toFixed(2)}%</dd></div><div><dt>SLO allowance</dt><dd>0.1%</dd></div></dl><div class="burn-equation"><span>${(bad/total*100).toFixed(2)}% ÷ 0.1%</span><strong>${burn.toFixed(1)}× burn</strong></div><p class="threshold-result ${burn>=a.threshold?'above':'below'}">${burn>=a.threshold?'Above':'Below'} the ${a.threshold}× threshold</p></section>`).join('')}</div><p class="rule-explanation">Both windows must reach the threshold in the same evaluation. The longer window confirms sustained impact; the shorter window checks that the problem is still happening.</p><div class="evidence-provenance"><span>${a.stale?'Last usable evaluation':'Evaluation'} · 12 Nov, ${a.stale?'10:36':'10:42'} UTC</span><span>Complete coverage at this evaluation</span><span>30-day rolling SLO · definition revision 3</span></div></div></details>`;}
  const quality = a => a.stale?'<div class="quality-warning"><strong>Evidence is stale · last evaluated 10:36 UTC</strong>Collection has stopped. The last known breach remains open; missing data cannot establish recovery.</div>':'';
  function acknowledgeButton(a,primary=true){return a.state==='firing'?`<button class="btn ${primary?'primary':''}" data-ack="${a.id}">Acknowledge</button>`:a.state==='ack'?`<span class="subline">${a.actor} acknowledged at ${a.ackTime} UTC</span>`:`<span class="subline">Resolved at ${a.resolved} UTC</span>`;}
  function history(a){return `<ol class="history">${a.state==='resolved'?`<li><time>${a.resolved}</time><div><strong>Resolved</strong><p>The recent burn window fell below ${a.threshold}× with complete, fresh evidence.</p></div></li>`:''}${a.late?'<li><time>10:20</time><div><strong>Detected after recovery</strong><p>Recorded during catch-up. No page sent.</p></div></li>':''}${a.stale?'<li><time>10:38</time><div><strong>Evidence became stale</strong><p>Alert state retained while collection is unavailable.</p></div></li>':''}${a.actor?`<li><time>${a.ackTime}</time><div><strong>Acknowledged by ${a.actor}</strong><p>This alert is being handled for the whole team.</p></div></li>`:''}<li><time>${a.since}</time><div><strong>Alert fired</strong><p>Both burn windows met the threshold in the same evaluation.</p></div></li></ol>`;}
  function detail(a,embedded=false){return `<div class="alert-detail-stack">${embedded?`<header class="embedded-detail-heading"><div><h2 class="detail-title">${a.policy}</h2><p class="detail-context"><a class="text-link slo-link" href="${sloLink(a)}" target="_blank" rel="noopener">${a.name} ↗</a><span>${a.severity} severity</span></p></div>${acknowledgeButton(a)}</header>`:''}<section class="panel verdict ${a.state}" aria-label="Alert status"><div class="flex">${badge(a.state)}<strong>${a.state==='resolved'?'Recent burn is below the threshold':a.state==='ack'?'Being handled. The last known condition still breaches.':'Both burn windows exceed the threshold.'}</strong></div><p>${a.state==='resolved'?`This occurrence ended at ${a.resolved} UTC.`:`Started ${a.since} UTC · open for ${a.age}`}</p></section><section class="panel burn-evidence" aria-label="Burn rate evidence"><div class="inset">${quality(a)}${a.late?'<div class="quality-warning"><strong>Detected after recovery</strong>This occurrence was recorded at 10:20 UTC during catch-up. It is retained in history, not shown as active.</div>':''}${windowCards(a)}${chart(a)}</div></section>${evidence(a)}<details class="panel lifecycle-card" open><summary>Lifecycle history <span>UTC</span></summary><div class="inset">${history(a)}</div></details></div>`;}
  function focus(items){const a=items.find(x=>x.id===selected)||items[0];selected=a.id;return `<div class="focus-layout"><section class="focus-hero"><div class="flex"><span class="eyebrow">${items.indexOf(a)+1} of ${items.length} open alerts</span>${badge(a.state)}</div><h2>${a.state==='firing'?`${a.service} needs your attention.`:`${a.service} is being handled.`}</h2><p class="lead">${a.stale?'Collection is stale. The last usable evaluation breached both windows.':`${a.name} is burning budget above its ${a.threshold}× threshold in both the ${duration(a.sw)} and ${duration(a.lw)} windows.`}</p>${windowCards(a)}${quality(a)}<div class="focus-actions">${acknowledgeButton(a)}<a class="btn" href="${href('detail',a.id)}">Inspect evidence</a><button class="quiet" data-action="next">Next alert →</button></div><div class="focus-progress" aria-hidden="true">${items.map(x=>`<i class="${x.id===a.id?'selected':''}"></i>`).join('')}</div></section><aside class="focus-aside"><h2>Also open</h2>${items.filter(x=>x.id!==a.id).map(x=>`<button class="queue-item" data-select="${x.id}"><span class="alert-title">${x.name}</span><span class="subline">${x.age} · ${x.severity} severity</span>${badge(x.state)}</button>`).join('')}<div class="focus-context"><strong>${alerts.filter(x=>x.state==='ack').length} / ${alerts.filter(x=>x.state!=='resolved').length}</strong>open alerts acknowledged by the team.<p>Acknowledging keeps the alert open while someone investigates.</p><a class="text-link" href="${href('history')}">Review resolved alerts →</a></div></aside></div>`;}
  const timePosition = t => {const [h,m]=t.split(':').map(Number);return Math.max(0,Math.min(100,((h*60+m)-(9*60+42))/60*100));};
  function timeline(items){const a=items.find(x=>x.id===selected)||items[0];selected=a.id;return `<div class="stack"><div class="time-intro"><div><h2>The last hour, together.</h2><p>Open and recently resolved alerts. Bars show when each occurrence was open.</p></div><span class="eyebrow">09:42–10:42 UTC</span></div><div class="panel timeline-shell"><div class="timeline-board"><div class="time-axis"><span>SLO / current state</span><div><span>09:42</span><span>09:57</span><span>10:12</span><span>10:27</span><span>Now</span></div></div>${alerts.filter(x=>(filter==='open'||x.state===filter)&&`${x.name} ${x.service} ${x.policy}`.toLowerCase().includes(search.toLowerCase())).map(x=>`<div class="time-lane"><button data-select="${x.id}"><strong>${x.name}</strong><span class="subline">${stateLabel(x.state)}${x.actor?' · '+x.actor:''}</span></button><div class="time-track">${x.state==='ack'?`<button class="time-bar" data-select="${x.id}" style="left:${timePosition(x.since)}%;width:${timePosition(x.ackTime)-timePosition(x.since)}%" aria-label="${x.name}, firing from ${x.since}">Firing</button><button class="time-bar ack ${x.ackTime==='10:42'?'just-ack':''} ${selected===x.id?'selected':''}" data-select="${x.id}" style="left:${Math.min(99,timePosition(x.ackTime))}%;width:${Math.max(1,100-timePosition(x.ackTime))}%" aria-label="${x.name}, acknowledged at ${x.ackTime}">Acknowledged</button>`:`<button class="time-bar ${x.state} ${selected===x.id?'selected':''}" data-select="${x.id}" style="left:${timePosition(x.since)}%;width:${(x.resolved?timePosition(x.resolved):100)-timePosition(x.since)}%" aria-label="Inspect ${x.name}, ${stateLabel(x.state)}">${x.state==='resolved'?'Resolved':'Firing'}</button>`}</div></div>`).join('')}</div></div><section class="panel"><div class="panel-head"><div><div class="eyebrow">Selected occurrence</div><h2>${a.name}</h2></div>${acknowledgeButton(a)}</div><div class="inset timeline-inspector"><div>${badge(a.state)}<p>${a.state==='resolved'?'Recovery is confirmed by complete evidence.':'The recent and sustained windows both breached the policy.'}</p>${quality(a)}${a.late?'<p class="subline">Detected after recovery · 10:20 UTC</p>':''}<a class="text-link" href="${href('detail',a.id)}">Open full evidence and history →</a></div>${windowCards(a)}</div></section></div>`;}
  function renderList(historyView=false){const items=visible(historyView),variant=route().variant;if(items.length&&!items.some(a=>a.id===selected))selected=items[0].id;root.innerHTML=header(historyView?'Alert history':variant==='d'?'Attention':variant==='e'?'Alert timeline':'Alerts')+tabs(historyView?'history':'list')+(historyView||variant==='a'?'':stats())+toolbar(historyView)+`<div id="results">${variant==='a'&&!historyView?refinedTable(items):!items.length?'<div class="panel empty"><h2>No alerts here</h2><p>Try another state or search. Policies continue evaluating.</p></div>':historyView?table(items):variant==='a'?table(items):variant==='b'?evidenceList(items):variant==='c'?`<div class="queue-layout">${queue(items)}${detail(items.find(a=>a.id===selected)||items[0],true)}</div>`:variant==='d'?focus(items):timeline(items)}</div>`;}
  function policyList(){root.innerHTML=header('Alert policies','Conditions that watch your SLOs.')+tabs('policies')+(success?`<div class="policy-success" role="status"><h2>${esc(success)} is ready</h2><p>Policy created in this mock. State: Normal. A new policy does not fabricate an active alert.</p></div>`:'')+`<div class="panel">${[...policies,...seed.map(a=>({name:a.policy,slo:a.name,short:a.sw,long:a.lw,threshold:a.threshold,severity:a.severity}))].map((p,i)=>`<div class="policy-row"><div><strong>${esc(p.name)}</strong><span class="subline">${esc(p.slo)} · ${p.conditions?p.conditions.map(c=>`${duration(windowMinutes(c,'short'))} + ${duration(windowMinutes(c,'long'))} ≥ ${esc(c.threshold)}×`).join(' OR '):`${duration(Number(p.short))} + ${duration(Number(p.long))} ≥ ${esc(p.threshold)}×`} · ${esc(p.severity)}</span></div>${i<policies.length?badge('normal'):'<span class="badge normal">Enabled</span>'}</div>`).join('')}</div>`;}
  function field(label,key,type='text',hint=''){return `<div class="field"><label for="${key}">${label}</label><input id="${key}" name="${key}" type="${type}" value="${esc(draft[key])}" ${type==='number'?'min="0.1" step="any"':''} required>${hint?`<small>${hint}</small>`:''}</div>`;}
  function section(n,title,body,classes=''){if(singlePageFlow())return `<section class="section ${classes}"><header><span class="step">${n}</span><h2>${title}</h2></header><div class="body">${body}</div></section>`;return `<section class="form-section ${classes}"><header><span class="step-number">0${n}</span><h2>${title}</h2></header><div class="fields">${body}</div></section>`;}
  const singlePageFlow=()=>['a','c'].includes(route().variant);
  const sloChoices=[...new Map(seed.map(a=>[a.name,{name:a.name,service:a.service}])).values()];
  function sloPicker(){const selected=sloChoices.find(s=>s.name===draft.slo);return `<div class="field" id="slo-picker"><label id="slo-label" ${selected?'':'for="slo"'}>SLO</label>${selected?`<div class="slo-selection" role="group" aria-labelledby="slo-label" aria-describedby="slo-context"><span class="nm" title="${esc(selected.name)}">${esc(selected.name)}</span><button class="change" type="button" id="change-slo" aria-label="Change SLO">Change</button></div>`:`<div class="combo"><input id="slo" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="slo-options" aria-describedby="slo-context" autocomplete="off" placeholder="Search SLOs…" required><ul class="combo-list" id="slo-options" role="listbox" aria-label="SLOs" hidden></ul></div><span class="sr-only" id="slo-results" role="status"></span>`}<small id="slo-context">${selected?'99.9% target · rolling 30 days':'Select an SLO to view its target.'}</small></div>`;}
  function initSloPicker(){
    const wrap=document.getElementById('slo-picker');if(!wrap)return;
    const change=document.getElementById('change-slo');if(change){change.onclick=()=>{draft.slo='';wrap.outerHTML=sloPicker();initSloPicker();document.getElementById('slo').focus();};return;}
    const input=document.getElementById('slo'),list=document.getElementById('slo-options');let active=-1,matches=[];
    const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;};
    const show=()=>{const term=input.value.trim().toLowerCase();matches=sloChoices.filter(s=>`${s.name} ${s.service}`.toLowerCase().includes(term));if(active>=matches.length)active=-1;list.innerHTML=matches.length?matches.map((s,i)=>`<li id="slo-option-${i}" role="option" aria-selected="${i===active}" data-slo-index="${i}"><span class="nm">${esc(s.name)}</span><span class="sm">${esc(s.service)} · 99.9% target · 30 days</span></li>`).join(''):'<li class="none">No SLOs found</li>';list.hidden=false;input.setAttribute('aria-expanded','true');if(active>=0){input.setAttribute('aria-activedescendant','slo-option-'+active);document.getElementById('slo-option-'+active).scrollIntoView({block:'nearest'});}else input.removeAttribute('aria-activedescendant');document.getElementById('slo-results').textContent=`${matches.length} SLOs found`;};
    const choose=i=>{if(!matches[i])return;draft.slo=matches[i].name;wrap.outerHTML=sloPicker();initSloPicker();document.getElementById('change-slo').focus();const previewEl=document.getElementById('policy-preview');if(previewEl)previewEl.innerHTML=preview();};
    input.addEventListener('focus',show);input.addEventListener('input',()=>{active=-1;show();});input.addEventListener('blur',close);
    input.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)show();active=Math.max(0,Math.min(matches.length-1,active+(e.key==='ArrowDown'?1:-1)));show();}else if(e.key==='Enter'&&!list.hidden){e.preventDefault();choose(active);}else if(e.key==='Escape'){e.preventDefault();close();}});
    list.addEventListener('pointerdown',e=>{if(e.target.closest('[data-slo-index]'))e.preventDefault();});list.addEventListener('click',e=>{const option=e.target.closest('[data-slo-index]');if(option)choose(Number(option.dataset.sloIndex));});
  }
  function identity(){if(singlePageFlow())return section(1,'Policy',`<div class="grid3 policy-fields">${field('Alert policy name','name','text')}${sloPicker()}${severityField()}</div>`);return section(1,'Policy details',`${field('Alert policy name','name','text')}${severityField()}${sloPicker()}`,'policy-identity');}
  const windowMinutes=(c,key)=>c[key+'Raw']!==undefined?NaN:Number(c[key])*({min:1,h:60,d:1440}[c[key+'Unit']]||1);
  function conditionKind(c){return windowMinutes(c,'short')===5&&windowMinutes(c,'long')===60&&Number(c.threshold)===14.4?'fast':windowMinutes(c,'short')===30&&windowMinutes(c,'long')===360&&Number(c.threshold)===6?'sustained':'custom';}
  const conditionNames={fast:'Fast burn',sustained:'Sustained burn',custom:'Custom condition'};
  const conditionDescriptions={fast:'Catch sudden, severe degradation.',sustained:'Catch persistent, lower-rate degradation.',custom:'Your own windows and burn threshold.'};
  function conditionValue(c,key){if(c[key+'Raw']!==undefined)return `<span class="invalid-value">${esc(c[key+'Raw']||'Set window')}</span>`;const unit=key==='threshold'?'×':c[key+'Unit'];return c[key]===''?'<span class="unset-value">Set '+(key==='threshold'?'threshold':'window')+'</span>':`<strong>${esc(c[key])}</strong><span>${esc(unit)}</span>`;}
  function conditionControl(c,key,label){const isWindow=key!=='threshold',value=isWindow?(c[key+'Raw']??(c[key]===''?'':c[key]+' '+c[key+'Unit'])):c[key];return `<div class="condition-control"><label class="mobile-condition-label" for="${c.id}-${key}">${label}</label><button type="button" class="condition-value" data-edit-condition="${c.id}-${key}" aria-label="Edit ${label.toLowerCase()} for ${conditionNames[conditionKind(c)]}">${conditionValue(c,key)}<svg aria-hidden="true" viewBox="0 0 16 16"><path d="m3 10 7-7 3 3-7 7H3v-3Zm6-6 3 3"/></svg></button><div class="condition-input" hidden><input id="${c.id}-${key}" ${isWindow?'type="text" data-duration="true" placeholder="5 min" title="Use minutes, hours or days: 5 min, 1 h, 2 d."':'type="number" min="0" step="any"'} required value="${esc(value)}" data-condition-id="${c.id}" data-condition-field="${key}" aria-label="${label} for ${conditionNames[conditionKind(c)]}">${isWindow?'':'<span class="unit" aria-hidden="true">×</span>'}</div></div>`;}

  function conditionRow(c){const kind=conditionKind(c);return `<div class="condition-row" data-condition-row="${c.id}"><div class="condition-identity"><strong>${conditionNames[kind]}</strong><small>${conditionDescriptions[kind]}</small></div>${conditionControl(c,'short','Short window')}${conditionControl(c,'long','Long window')}${conditionControl(c,'threshold','Burn threshold')}<button type="button" class="quiet remove-condition" data-remove-condition="${c.id}" aria-label="Remove ${conditionNames[kind]}" ${draft.conditions.length===1?'disabled title="Keep at least one condition"':''}><svg aria-hidden="true" viewBox="0 0 16 16"><path d="M4 4l8 8M12 4l-8 8"/></svg></button></div>`;}
  function multiConditions(){return section(2,'Conditions',`<p class="condition-intro">An alert fires when the burn rate reaches the threshold in <strong>both windows of any one condition</strong>.</p><div class="condition-grid-head" aria-hidden="true"><span>Condition</span><span>Short window</span><span>Long window</span><span>Burn threshold</span><span></span></div><div class="condition-rows">${draft.conditions.map(conditionRow).join('')}</div><div class="condition-footer"><button class="btn" type="button" data-action="condition-menu" aria-haspopup="dialog" aria-expanded="false" aria-controls="condition-menu">＋ Add condition</button></div><div id="condition-menu" class="condition-menu" popover="auto" role="dialog" aria-label="Add a condition"><div class="condition-menu-heading">Add a condition</div>${['fast','sustained','custom'].map(kind=>{const exists=kind!=='custom'&&draft.conditions.some(c=>conditionKind(c)===kind);return `<button type="button" data-add-condition="${kind}" ${exists?'disabled':''}><strong>${conditionNames[kind]}${exists?' <span>Added</span>':''}</strong><small>${conditionDescriptions[kind]}</small></button>`;}).join('')}<p>Presets are starting points for a 30-day SLO.</p></div>`,'conditions-section');}
  function openConditionEditor(control){if(!control||control.classList.contains('editing'))return;control._previous=Array.from(control.querySelectorAll('[data-condition-field]'),el=>[el,el.value]);control.classList.add('editing');control.querySelector('.condition-value').hidden=true;control.querySelector('.condition-input').hidden=false;const input=control.querySelector('input');input.focus({preventScroll:true});input.select();}
  function closeConditionEditor(control,restore=false,returnFocus=false){if(!control?.classList.contains('editing'))return;if(restore)for(const [el,value] of control._previous){el.value=value;updateCondition(el);}const input=control.querySelector('input'),c=draft.conditions.find(c=>c.id===input.dataset.conditionId),key=input.dataset.conditionField,button=control.querySelector('.condition-value');if(input.dataset.duration&&c[key+'Raw']===undefined)input.value=c[key]===''?'':c[key]+' '+c[key+'Unit'];button.innerHTML=conditionValue(c,key)+'<svg aria-hidden="true" viewBox="0 0 16 16"><path d="m3 10 7-7 3 3-7 7H3v-3Zm6-6 3 3"/></svg>';control.classList.remove('editing');control.querySelector('.condition-input').hidden=true;button.hidden=false;if(returnFocus)button.focus({preventScroll:true});}
  function refreshConditions(focusId){const error=document.getElementById('form-error');if(error){error.hidden=true;error.textContent='';}document.getElementById('condition-menu')?.hidePopover();root.querySelector('.conditions-section').outerHTML=multiConditions();if(focusId)openConditionEditor(document.getElementById(focusId)?.closest('.condition-control'));else root.querySelector('[data-action="condition-menu"]')?.focus({preventScroll:true});}
  function updateCondition(target){const c=draft.conditions.find(c=>c.id===target.dataset.conditionId);if(!c)return;const field=target.dataset.conditionField;if(target.dataset.duration){const match=target.value.trim().match(/^(\d+(?:\.\d+)?)\s*(min(?:ute)?s?|m|h(?:our)?s?|d(?:ay)?s?)?$/i);if(match){c[field]=match[1];const unit=match[2]?.toLowerCase();if(unit)c[field+'Unit']=unit.startsWith('m')?'min':unit.startsWith('h')?'h':'d';delete c[field+'Raw'];}else c[field+'Raw']=target.value;}else c[field]=target.value;const row=target.closest('.condition-row'),kind=conditionKind(c);row.querySelector('.condition-identity strong').textContent=conditionNames[kind];row.querySelector('.condition-identity small').textContent=conditionDescriptions[kind];row.querySelectorAll('[data-edit-condition]').forEach(button=>{const key=button.dataset.editCondition.split('-').pop();button.setAttribute('aria-label','Edit '+{short:'short window',long:'long window',threshold:'burn threshold'}[key]+' for '+conditionNames[kind]);});row.querySelector('.remove-condition').setAttribute('aria-label','Remove '+conditionNames[kind]);row.querySelectorAll('[data-condition-field]').forEach(el=>{const field=el.dataset.conditionField,key=field.replace('Unit',''),label={short:'Short window',long:'Long window',threshold:'Burn threshold'}[key];el.setAttribute('aria-label',label+(field.endsWith('Unit')?' unit':'')+' for '+conditionNames[kind]);});target.removeAttribute('aria-invalid');target.removeAttribute('aria-describedby');}
  function conditions(){if(singlePageFlow())return multiConditions();return section(2,'Set the conditions',`<fieldset style="border:0;padding:0;margin:0"><legend class="sr-only">Starting preset</legend><div class="preset-choices"><label class="preset-choice"><input type="radio" name="preset" value="fast" ${draft.preset==='fast'?'checked':''}><strong>Fast burn</strong><small>5 min + 1 h at 14.4×<br>Detect rapid budget consumption.</small></label><label class="preset-choice"><input type="radio" name="preset" value="slow" ${draft.preset==='slow'?'checked':''}><strong>Sustained burn</strong><small>30 min + 6 h at 6×<br>Detect sustained degradation.</small></label></div></fieldset><div class="field-grid triple">${field('Short window · minutes','short','number')}${field('Long window · minutes','long','number')}${field('Burn threshold · ×','threshold','number')}</div><p class="subline" style="margin:0">Both windows must meet the threshold. These starting presets assume a 30-day SLO. Edit the values to customize.</p>`);}
  function severityField(){return `<div class="field severity-field"><span class="control-label" id="severity-label">Severity</span><div class="seg severity-segments" role="radiogroup" aria-labelledby="severity-label">${['Low','Medium','High'].map(v=>`<button type="button" role="radio" data-severity="${v}" aria-checked="${v===draft.severity}" tabindex="${v===draft.severity?0:-1}">${v}</button>`).join('')}</div></div>`;}
  function chooseSeverity(value){syncDraft({name:'severity',value});root.querySelectorAll('[data-severity]').forEach(el=>{const chosen=el.dataset.severity===value;el.setAttribute('aria-checked',chosen);el.tabIndex=chosen?0:-1;});}
  document.addEventListener('keydown',e=>{const current=e.target.closest('[data-severity]');if(!current||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...root.querySelectorAll('[data-severity]')],i=buttons.indexOf(current),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(['ArrowRight','ArrowDown'].includes(e.key)?1:-1)+buttons.length)%buttons.length;chooseSeverity(buttons[next].dataset.severity);buttons[next].focus();});
  function destinations(){if(singlePageFlow())return section(3,'Alert destinations',`<div class="destination-current"><div><strong>In Almanac</strong><span class="subline">Email, Slack and PagerDuty are planned for a later phase.</span></div><span class="destination-enabled">Always on</span></div>`);return section(3,'Alert destinations',`<div class="destination-current"><div><strong>In Almanac</strong><span class="subline">Alerts appear in your team’s alert list.</span></div><span class="destination-enabled">Always on</span></div><p class="destination-future">Email, Slack and PagerDuty are planned for a later phase.</p>`);}
  function preview(){const valid=Number(draft.short)>0&&Number(draft.long)>0&&Number(draft.threshold)>0;return `<span class="preview-label">Policy preview</span><h2>${esc(draft.name||'Your new alert')}</h2><p>Watch <strong>${esc(draft.slo||'Choose an SLO')}</strong>.</p><div class="preview-rule"><strong>Both windows ≥ ${esc(draft.threshold||'—')}×</strong><span>${valid?`${duration(Number(draft.short))} recent + ${duration(Number(draft.long))} sustained`:'Enter window lengths and a threshold'}</span></div><p><strong>When it fires</strong><br>Create a ${esc(draft.severity.toLowerCase())}-severity alert when both windows meet the threshold using complete, fresh data.</p><p><strong>When it resolves</strong><br>Either window falls below the threshold with complete, fresh data.</p><p><strong>Alert destinations</strong><br>In Almanac</p><p><strong>While acknowledged</strong><br>Evaluation continues. The whole team sees who is handling it.</p><div class="quality-warning"><strong>Missing data is not recovery</strong>Preserve the open alert and show the evidence gap.</div><span class="subline">No additional waiting period. No automatic acknowledgement timeout.</span>`;}
  function windowMap(){return `<div class="window-map"><h2>One decision. Two perspectives.</h2><p class="subline">The long window establishes sustained burn. The short window checks recent behavior.</p><div class="window-scale" aria-label="Conceptual paired windows, not to scale"><div class="long-window">Sustained window</div><div class="short-window">Recent</div></div><div class="flex" style="justify-content:space-between"><span class="eyebrow">Earlier</span><span class="eyebrow">Evaluation time</span></div></div>`;}
  function renderNew(){
    draft ||= initialDraft();const v=route().variant;
    if(singlePageFlow()){
      root.innerHTML=`<nav class="crumbs" aria-label="Breadcrumb"><a href="${href('policies')}">Alert policies</a><span>/</span>New alert policy</nav><div class="page-head"><div><h1 tabindex="-1">New alert policy</h1><div class="sub">Choose an SLO, set the burn conditions and label the urgency.</div></div></div><div id="form-error" class="form-error" role="alert" hidden></div><form id="policy-form" class="form alert-create-form" novalidate>${identity()}${conditions()}${destinations()}<div class="actions"><a class="btn" href="${href('policies')}">Cancel</a><button class="btn primary" type="submit">Create alert policy</button></div></form>`;
    }else{
      root.innerHTML=`<a class="crumb" href="${href('policies')}">← Alert policies</a>`+header('New alert policy','Choose an SLO and define when your team should investigate.',false)+(v==='d'?'<div class="sentence-intro">When this SLO burns budget <em>too quickly</em>,<br>bring it to our attention.</div>':'')+(v==='e'?windowMap():'')+`<div id="form-error" class="form-error" role="alert" hidden></div><form id="policy-form" novalidate><div class="new-layout with-preview"><div>${identity()}${conditions()}${destinations()}</div><aside class="panel preview-panel"><div class="inset" id="policy-preview">${preview()}</div></aside></div><div class="form-actions"><div class="flex"><a class="btn" href="${href('policies')}">Cancel</a><button class="btn primary" type="submit">Create alert policy</button></div></div></form>`;
    }
    initSloPicker();
  }
  function validate(){if(!draft.name.trim())return ['name','Enter an alert policy name.'];if(!sloChoices.some(s=>s.name===draft.slo))return ['slo','Search for and select an SLO.'];if(singlePageFlow()){if(!draft.conditions.length)return ['name','Add at least one condition.'];for(const c of draft.conditions){if(c.shortRaw!==undefined)return [c.id+'-short','Enter a duration such as 5 min, 1 h or 2 d.'];if(c.longRaw!==undefined)return [c.id+'-long','Enter a duration such as 5 min, 1 h or 2 d.'];const short=windowMinutes(c,'short'),long=windowMinutes(c,'long');if(!Number.isInteger(short)||short<1)return [c.id+'-short','Use a positive window that is a whole number of minutes.'];if(!Number.isInteger(long)||long<short||long>43200)return [c.id+'-long','The long window must be at least as long as the short window and no longer than 30 days.'];if(!Number.isFinite(Number(c.threshold))||Number(c.threshold)<=0||Number(c.threshold)>1000)return [c.id+'-threshold','Use a positive burn threshold up to 1,000×.'];}return null;}if(!Number.isInteger(Number(draft.short))||Number(draft.short)<1)return ['short','Use a whole number of minutes for the short window.'];if(!Number.isInteger(Number(draft.long))||Number(draft.long)<Number(draft.short))return ['long','The long window must be a whole number of minutes, at least as long as the short window.'];if(Number(draft.long)>43200)return ['long','The long window cannot exceed the 30 days of retained demo data.'];if(!Number.isFinite(Number(draft.threshold))||Number(draft.threshold)<=0||Number(draft.threshold)>1000)return ['threshold','Use a positive burn threshold up to 1,000× for a 99.9% target.'];return null;}
  function render(focusHeading=false){review();const r=route();root.classList.toggle('creation-single',r.view==='new'&&singlePageFlow());if(r.view==='new')renderNew();else if(r.view==='policies')policyList();else if(r.view==='detail'){const a=alerts.find(x=>x.id===r.id)||alerts[0];root.innerHTML=`<a class="crumb" href="${href()}">← Alerts</a><div class="heading"><div><h1 tabindex="-1">${a.policy}</h1><p class="detail-context"><a class="text-link slo-link" href="${sloLink(a)}" target="_blank" rel="noopener">${a.name} ↗</a><span>${a.severity} severity</span></p></div><div class="heading-actions">${acknowledgeButton(a)}</div></div>`+detail(a);}else renderList(r.view==='history');if(focusHeading)root.querySelector('h1')?.focus({preventScroll:true});}
  function syncDraft(target){if(!draft||!target.name)return;if(target.name==='preset'){draft.preset=target.value;Object.assign(draft,target.value==='fast'?{short:'5',long:'60',threshold:'14.4'}:{short:'30',long:'360',threshold:'6'});for(const key of ['short','long','threshold']){const el=document.getElementById(key);if(el)el.value=draft[key];}}else draft[target.name]=target.value;const previewEl=document.getElementById('policy-preview');if(previewEl)previewEl.innerHTML=preview();}
  document.addEventListener('input',e=>{if(e.target.dataset.conditionField){updateCondition(e.target);return;}if(e.target.id==='search'){const position=e.target.selectionStart;search=e.target.value;renderList(route().view==='history');const el=document.getElementById('search');el.focus();el.setSelectionRange(position,position);}else if(e.target.closest('#policy-form'))syncDraft(e.target);});
  document.addEventListener('change',e=>{if(e.target.dataset.conditionField){updateCondition(e.target);return;}if(e.target.id==='state-filter'){filter=e.target.value;renderList(route().view==='history');document.getElementById('state-filter').focus();}else if(e.target.closest('#policy-form'))syncDraft(e.target);});
  document.addEventListener('focusout',e=>{const control=e.target.closest('.condition-control.editing');if(control&&!control.contains(e.relatedTarget))requestAnimationFrame(()=>{if(control.isConnected&&!control.contains(document.activeElement))closeConditionEditor(control);});});
  document.addEventListener('keydown',e=>{const control=e.target.closest('.condition-control.editing');if(!control||!['Enter','Escape'].includes(e.key))return;e.preventDefault();closeConditionEditor(control,e.key==='Escape',true);});
  document.addEventListener('click',e=>{
    const edit=e.target.closest('[data-edit-condition]');if(edit){openConditionEditor(edit.closest('.condition-control'));return;}
    const quantity=e.target.closest('.condition-input');if(quantity&&!e.target.closest('input,select')){quantity.querySelector('input').focus();return;}
    const conditionLabel=e.target.closest('.mobile-condition-label');if(conditionLabel){openConditionEditor(conditionLabel.closest('.condition-control'));return;}

    const addCondition=e.target.closest('[data-add-condition]');if(addCondition){const c=newCondition(addCondition.dataset.addCondition);draft.conditions.push(c);refreshConditions(c.id+'-short');return;}
    const removeCondition=e.target.closest('[data-remove-condition]');if(removeCondition){if(draft.conditions.length>1){draft.conditions=draft.conditions.filter(c=>c.id!==removeCondition.dataset.removeCondition);refreshConditions();}return;}

    const severity=e.target.closest('[data-severity]');if(severity){chooseSeverity(severity.dataset.severity);return;}
    const preset=e.target.closest('[data-preset]');if(preset){syncDraft({name:'preset',value:preset.dataset.preset});root.querySelectorAll('[data-preset]').forEach(el=>el.setAttribute('aria-pressed',el===preset));return;}
    const filterButton=e.target.closest('[data-filter]');if(filterButton){openFilter(filterButton);return;}
    const remove=e.target.closest('[data-remove-filter]');if(remove){columnFilters[remove.dataset.removeFilter]='';renderList();root.querySelector('[data-filter=all]').focus();return;}

    const ack=e.target.closest('[data-ack]');if(ack){const rowAction=ack.closest('[data-open]');const a=alerts.find(x=>x.id===ack.dataset.ack);if(a?.state==='firing'){a.state='ack';a.actor='Jamie Morgan';a.ackTime='10:42';render(!rowAction);if(rowAction)(root.querySelector(`[data-open="${a.id}"] .alert-title`)||root.querySelector('.row-ack')||root.querySelector('[data-filter=state]')||document.getElementById('state-filter'))?.focus({preventScroll:true});say(`${a.name} acknowledged for the whole team.`);}return;}
    const row=e.target.closest('[data-open]');
    if(row&&!e.defaultPrevented&&e.button===0&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&!e.altKey&&!e.target.closest('a,button,input,select,textarea,summary,[role="button"]')&&!window.getSelection()?.toString()){location.hash=href('detail',row.dataset.open);return;}
    const select=e.target.closest('[data-select]');if(select){selected=select.dataset.select;if(route().variant==='e'&&alerts.find(x=>x.id===selected)?.state==='resolved'){location.hash=href('detail',selected);return;}render();const current=root.querySelector('[data-select="'+selected+'"]');current?.focus({preventScroll:true});return;}
    const action=e.target.closest('[data-action]')?.dataset.action;
    if(action==='condition-menu'){const menu=document.getElementById('condition-menu'),trigger=e.target.closest('[data-action]');menu.querySelectorAll('[data-add-condition]').forEach(button=>{const kind=button.dataset.addCondition;button.disabled=kind!=='custom'&&draft.conditions.some(c=>conditionKind(c)===kind);button.querySelector('strong').innerHTML=conditionNames[kind]+(button.disabled?' <span>Added</span>':'');});const rect=trigger.getBoundingClientRect();menu.style.left=Math.max(12,Math.min(rect.left,innerWidth-332))+'px';menu.showPopover();const height=menu.offsetHeight,below=rect.bottom+8,above=rect.top-height-8;menu.style.top=Math.max(12,below+height<=innerHeight-12?below:above>=12?above:innerHeight-height-12)+'px';trigger.setAttribute('aria-expanded','true');menu.ontoggle=event=>trigger.setAttribute('aria-expanded',String(event.newState==='open'));menu.querySelector('button:not(:disabled)')?.focus();}
    if(action==='theme'){document.documentElement.classList.toggle('dark');review();}
    if(action==='group'){groupBy=groupBy==='slo'?'none':'slo';renderList();document.getElementById('group-by').focus();}
    if(action==='close-filter'){closeFilter();filterTrigger?.focus();}
    if(action==='reset-panel'){filterPanel.querySelectorAll('input,select').forEach(el=>el.value='');}
    if(action==='clear-filters'){clearColumnFilters();search='';renderList();document.getElementById('search').focus();}
    if(action==='reset'){clearColumnFilters();groupBy='none';alerts=structuredClone(seed);policies=[];draft=undefined;success='';filter='open';search='';selected='checkout';render();say('Demo reset.');}
    if(action==='next'){const items=visible();selected=items[(items.findIndex(x=>x.id===selected)+1)%items.length].id;render();root.querySelector('[data-action="next"]')?.focus();}
  });
  document.addEventListener('submit',e=>{if(e.target.id==='filter-form'){e.preventDefault();for(const [key,value] of new FormData(e.target))columnFilters[key]=value;const key=filterTrigger.dataset.filter;closeFilter();renderList();root.querySelector(`[data-filter="${key}"]`)?.focus();return;}if(e.target.id!=='policy-form')return;e.preventDefault();const r=route();let error=validate();if(error){const box=document.getElementById('form-error');box.hidden=false;box.textContent=error[1];const fieldEl=document.getElementById(error[0]);openConditionEditor(fieldEl?.closest('.condition-control'));fieldEl?.setAttribute('aria-invalid','true');fieldEl?.setAttribute('aria-describedby','form-error');fieldEl?.focus();return;}policies.unshift(singlePageFlow()?structuredClone(draft):{...draft,conditions:undefined});success=draft.name;draft=undefined;location.hash=href('policies');});
  let priorView='';window.addEventListener('hashchange',()=>{closeFilter();const r=route();if(r.view!==priorView){search='';filter='open';}priorView=r.view;render(true);window.scrollTo(0,0);});
  shell();render();
})();
